    lw = s["log_weights"][:]; w = np.exp(lw - lw.max())
    print(name)
    for k in ["diffuse_delta", "diffuse_Ebump", "diffuse_tau_noll", "dust_ratio", "zh_beta_unit", "log_f_calib", "logmass"]:
        x = s[k][:]
        print(f"  {k:18s} q01,16,50,84,99 =", np.round(wq(x, w, [0.01,.16,.5,.84,.99]), 3), " min/max", np.round([x.min(), x.max()],3))
EOF",
